package io.github.chronicle.core.encounters;

import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;

/** At-most-once operation evidence. A claimed entry is intentionally never made runnable again. */
public record EncounterOperation(UUID operationId, UUID actorId, String groupId, String groupFingerprint, String planHash, List<EncounterSpawnEntry> entries, Terminal terminal, Optional<EncounterTarget> target) {
    public EncounterOperation(UUID operationId,UUID actorId,String groupId,String groupFingerprint,String planHash,List<EncounterSpawnEntry> entries,Terminal terminal){this(operationId,actorId,groupId,groupFingerprint,planHash,entries,terminal,Optional.empty());}
    public enum Terminal { OPEN, COMPLETE, UNCERTAIN, REVIEWED, CANCELLED }
    public EncounterOperation { Objects.requireNonNull(operationId,"operation UUID is required"); Objects.requireNonNull(actorId,"actor UUID is required"); groupId=EncounterIds.registry(groupId,"encounter group ID"); groupFingerprint=hash(groupFingerprint,"group fingerprint"); planHash=hash(planHash,"plan hash"); if(entries==null||entries.isEmpty()||entries.size()>64)throw new IllegalArgumentException("operation must contain 1 to 64 planned entries"); entries=List.copyOf(entries); Set<UUID> ids=new HashSet<>();for(EncounterSpawnEntry entry:entries)if(!ids.add(entry.entityId()))throw new IllegalArgumentException("operation contains duplicate entity UUID"); target=Objects.requireNonNull(target,"target pin is required"); if(!planHash.equals(planHash(operationId,actorId,groupFingerprint,entries,target)))throw new IllegalArgumentException("operation plan hash does not match its immutable identity"); Objects.requireNonNull(terminal,"operation terminal state is required"); if(terminal==Terminal.CANCELLED&&entries.stream().anyMatch(e->e.stage()==EncounterSpawnEntry.Stage.CLAIMED))throw new IllegalArgumentException("claimed entries require uncertainty review"); boolean all=entries.stream().allMatch(e->e.stage()==EncounterSpawnEntry.Stage.SPAWNED); if(terminal==Terminal.COMPLETE&&!all)throw new IllegalArgumentException("only fully spawned operation may complete"); if((terminal==Terminal.UNCERTAIN||terminal==Terminal.REVIEWED)&&entries.stream().allMatch(e->e.stage()==EncounterSpawnEntry.Stage.PLANNED))throw new IllegalArgumentException("reviewable operation must retain an attempted entry"); }
    public EncounterOperation claim(UUID entityId){ requireOpen(); return replace(entityId,EncounterSpawnEntry::claim,Terminal.OPEN); }
    public EncounterOperation markSpawned(UUID entityId){ requireOpen(); return replace(entityId,EncounterSpawnEntry::spawned,Terminal.OPEN); }
    public EncounterOperation complete(){ requireOpen(); if(entries.stream().anyMatch(e->e.stage()!=EncounterSpawnEntry.Stage.SPAWNED))throw new IllegalStateException("operation has unspawned entries"); return new EncounterOperation(operationId,actorId,groupId,groupFingerprint,planHash,entries,Terminal.COMPLETE,target); }
    public EncounterOperation uncertain(){ requireOpen(); if(entries.stream().allMatch(e->e.stage()==EncounterSpawnEntry.Stage.PLANNED))throw new IllegalStateException("only an attempted operation may become uncertain"); return new EncounterOperation(operationId,actorId,groupId,groupFingerprint,planHash,entries,Terminal.UNCERTAIN,target); }
    /** Operator acceptance preserves every exact stage and permanently forbids remaining spawns. */
    public EncounterOperation reviewed(){if(terminal!=Terminal.UNCERTAIN)throw new IllegalStateException("only an uncertain operation may be reviewed");return new EncounterOperation(operationId,actorId,groupId,groupFingerprint,planHash,entries,Terminal.REVIEWED,target);}
    /** Explicitly skips the remaining OPEN plan without misreporting a preflight refusal as uncertainty. */
    public EncounterOperation cancelled(){requireOpen();if(entries.stream().anyMatch(e->e.stage()==EncounterSpawnEntry.Stage.CLAIMED))throw new IllegalStateException("claimed entries require uncertainty review before resolution");return new EncounterOperation(operationId,actorId,groupId,groupFingerprint,planHash,entries,Terminal.CANCELLED,target);}
    public boolean resolved(){return terminal==Terminal.COMPLETE||terminal==Terminal.REVIEWED||terminal==Terminal.CANCELLED;}
    private EncounterOperation replace(UUID id,java.util.function.UnaryOperator<EncounterSpawnEntry> change,Terminal next){Objects.requireNonNull(id,"entity UUID is required");List<EncounterSpawnEntry> updated=new ArrayList<>();boolean found=false;for(EncounterSpawnEntry e:entries){if(e.entityId().equals(id)){updated.add(change.apply(e));found=true;}else updated.add(e);}if(!found)throw new IllegalArgumentException("entity UUID is not in operation plan");return new EncounterOperation(operationId,actorId,groupId,groupFingerprint,planHash,updated,next,target);}
    private void requireOpen(){if(terminal!=Terminal.OPEN)throw new IllegalStateException("terminal operation cannot be replayed");}
    private static String hash(String value,String label){if(value==null||!value.matches("[0-9a-f]{64}"))throw new IllegalArgumentException(label+" must be a lowercase SHA-256 hex digest");return value;}
    public static String fingerprint(EncounterGroup group){Objects.requireNonNull(group,"group is required");StringBuilder value=new StringBuilder(group.id()).append('\n').append(group.label()).append('\n').append(group.description());for(EncounterMember m:group.members())value.append('\n').append(m.entityType()).append(':').append(m.count());return sha(value.toString());}
    public static String planHash(UUID operationId,UUID actorId,String groupFingerprint,List<EncounterSpawnEntry> entries){StringBuilder value=new StringBuilder(operationId.toString()).append('\n').append(actorId).append('\n').append(groupFingerprint);for(EncounterSpawnEntry e:entries)value.append('\n').append(e.entityId()).append('|').append(e.entityType()).append('|').append(e.dimension()).append('|').append(Double.toHexString(e.x())).append('|').append(Double.toHexString(e.y())).append('|').append(Double.toHexString(e.z()));return sha(value.toString());}
    /** Legacy empty pins preserve the original byte-for-byte plan digest. */
    public static String planHash(UUID operationId,UUID actorId,String fingerprint,List<EncounterSpawnEntry> entries,Optional<EncounterTarget> target){String legacy=planHash(operationId,actorId,fingerprint,entries);return target.map(pin->sha("encounter-plan-v2\n"+legacy+"\n"+pin.kind()+"|"+pin.siteId()+"|"+pin.siteRevision())).orElse(legacy);}
    private static String sha(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException("SHA-256 unavailable",e);}}
}
